 using W=NativeMidiWrapper;using C=NativeMidiProgramCommit;using H=NativeMidiEventHelper;using J=std::variant<std::monostate,W,C,H>;
public:enum class External:uint8_t{None,SysEx,Dsp,Load,Display};struct CodeRange{uint32_t begin,end;};inline static constexpr std::array<CodeRange,4>CodeRanges{{{0x2d5c,0x2d7e},{0x2f68,0x2f72},{0x33ca,0x33f4},{0x4c5e,0x4c76}}};static bool candidate(uint32_t pc){for(auto r:CodeRanges)if(pc>=r.begin&&pc<r.end)return true;return false;}void reset(){for(auto&j:jobs_)j.emplace<std::monostate>();depth_=0;}bool active()const{return depth_!=0;}External external()const{if(!depth_)return External::None;if(auto*p=std::get_if<W>(&jobs_[depth_-1]);p&&p->task().awaitingChild()){using C=MidiWrapperTask::Child;return p->task().child()==C::SysEx?External::SysEx:p->task().child()==C::Dsp?External::Dsp:External::None;}if(auto*p=std::get_if<C>(&jobs_[depth_-1]);p&&p->task().awaitingChild())return p->task().child()==MidiProgramCommitTask::Child::Load?External::Load:External::Display;return External::None;}
 bool step(Stage1Cpu&c){if(midi_projection::blocked(c))return false;for(unsigned i=0;i<12;++i){if(!depth_){using K=MidiWrapperTask::Kind;switch(uint32_t(c.getPC())){case 0x2f68:jobs_[depth_++].emplace<W>(K::SysEx);break;case 0x2f6c:jobs_[depth_++].emplace<W>(K::NoopCall);break;case 0x2f70:jobs_[depth_++].emplace<W>(K::Noop);break;case 0x33ca:jobs_[depth_++].emplace<W>(K::Program);break;case 0x33ec:jobs_[depth_++].emplace<W>(K::Dsp);break;case 0x33f2:jobs_[depth_++].emplace<W>(K::EmptyDsp);break;case 0x4c5e:jobs_[depth_++].emplace<C>(uint8_t(c.reg8(5)));break;default:return false;}}auto&j=jobs_[depth_-1];if(auto*p=std::get_if<W>(&j);p&&p->task().awaitingChild()){if(p->resumeChild(c))continue;if(depth_==jobs_.size())return false;auto ch=p->task().child();if(ch==MidiWrapperTask::Child::Noop&&uint32_t(c.getPC())==0x2f70)jobs_[depth_++].emplace<W>(MidiWrapperTask::Kind::Noop);else if(ch==MidiWrapperTask::Child::Match&&uint32_t(c.getPC())==0x2d5c)jobs_[depth_++].emplace<H>(MidiEventHelperTask::Kind::ChannelMatch);else if(ch==MidiWrapperTask::Child::Program&&uint32_t(c.getPC())==0x4c5e)jobs_[depth_++].emplace<C>(uint8_t(c.reg8(5)));else return false;continue;}if(auto*p=std::get_if<C>(&j);p&&p->task().awaitingChild()&&!p->resumeChild(c))return false;bool ok=std::visit([&](auto&v)->bool{using V=std::decay_t<decltype(v)>;if constexpr(std::is_same_v<V,std::monostate>)return false;else return v.step(c);},j);if(!ok)return false;bool done=std::visit([](const auto&v)->bool{using V=std::decay_t<decltype(v)>;if constexpr(std::is_same_v<V,std::monostate>)return true;else return v.task().complete();},j);if(done){j.emplace<std::monostate>();--depth_;}return true;}return false;}
